296			t.Fatal("expected non-zero exit")
297		}
298		if stdout != "" {
299			t.Fatalf("expected empty stdout, got %q", stdout)
300		}
301		if !strings.Contains(stderr, "JSON 格式错误") {
302			t.Fatalf("stderr should report a JSON format error, got %q", stderr)
303		}
304	}
