	if err != nil {
		t.Fatal(err)
	}
	for i, raw := range withExtra {
		in, err := ParseReleaseInput([]byte(raw))
		if err != nil {
			t.Fatalf("case %d: extra huge number must be accepted, got %v", i, err)
